#pragma once
// pse.ids service (ids.cpp): game layers register their ID database here; plugins read it through the public
// interface pse.ids (pse/include/pse/pse_ids.h, docs/sdk/reference/ids.md). Game-neutral: the tables come from the
// game layer (generated by scripts/gen_ids.py into src/generated/pse_ids_<game>.h). NOT part of the SDK.
#include <cstdint>
#include <string>

#include "loader.h"
#include "pse/pse_ids.h"

namespace pse::ids {

// ---- generated table layout (scripts/gen_ids.py writes these; keep both in step) ------------------------------
struct EntryDef {
    uint32_t id;
    const char* name;
    uint32_t kind;          // PSEIdKind
};
struct AddressDef {
    uint32_t id;
    uint32_t va;            // the address the id resolves to on this build
    uint32_t checkVa;       // where the signature is checked (va, or a code reference for globals); 0 = no check
    const char* signature;  // hex, "??" = any byte; "" = not verified
};
struct BuildDef {
    const char* name;       // "steam-gog-1.0"
    const char* notes;
    uint32_t timestamp;     // PE TimeDateStamp + SizeOfImage pick the build
    uint32_t sizeOfImage;
    const char* sha256;     // informational (the plugin doesn't hash the exe at start-up)
    const AddressDef* addresses;
    uint32_t addressCount;
};
struct PublishedDef {
    uint32_t id;
    const char* name;
};
struct GameDef {
    uint32_t size;          // sizeof(GameDef)
    const char* gameId;     // "ds1"
    const char* gameName;
    uint32_t databaseVersion;
    const EntryDef* entries;    // sorted by id
    uint32_t entryCount;
    const BuildDef* builds;
    uint32_t buildCount;
    const PublishedDef* published;
    uint32_t publishedCount;
};

// ---- the running image ----------------------------------------------------------------------------------------
// Where signatures are read from: the live process (ProcessImage) or, in tests, the mapped original exe.
struct ImageView {
    uint32_t timestamp = 0;
    uint32_t sizeOfImage = 0;
    // Copies len bytes at va; false = not readable. Must not throw.
    bool (*read)(uint32_t va, void* out, uint32_t len, void* ctx) = nullptr;
    void* ctx = nullptr;
};
// The main module of this process (GetModuleHandle(NULL)): PE header fields + a fault-safe memory reader.
bool ProcessImage(ImageView* out);

struct RegisterSummary {
    std::string build;          // "" = unknown exe
    uint32_t ids = 0, resolved = 0, mismatched = 0, missing = 0;   // missing = no address for this build
};

// Registers (or replaces) a game's database: picks the build from the image header, checks every signature once and
// caches the addresses. Call it before anything patches the game (signatures are the ORIGINAL bytes).
// owner = the plugin that serves pse.ids and logs (phase 1: the loader, pse::FindPlugin("pse"); split: the game
// layer's own handle in PSEGame_Init). It publishes the interface (pse::MessagingInterface()->RegisterInterface
// (owner, PSE_IDS_INTERFACE, 1, ...)) and logs through pse::LogLine(owner, ...); 0 = neither (tests).
// A mismatch logs one line per id and that id resolves to 0; an unknown build logs one line and every id resolves
// to 0. Never faults. PSE_E_INVALID_ARG = bad table (size / NULL / unsorted ids).
// Only uses declarations of loader.h, so this file builds into pse_core (the loader) or, through pse_hostlink, into a
// game layer DLL.
PSEResult RegisterGame(const GameDef& def, const ImageView& image, PSEPluginHandle owner,
                       RegisterSummary* out = nullptr);
// The same against this process (ProcessImage).
PSEResult RegisterGameForProcess(const GameDef& def, PSEPluginHandle owner, RegisterSummary* out = nullptr);

// The interface table (also reachable through Query(PSE_IDS_INTERFACE, 1) once a game is registered).
const PSEIdsInterface* Interface();

// Signature helpers (also used by the tests): hex with "??" wildcards, 1..16 bytes.
bool SignatureMatches(const ImageView& image, uint32_t va, const char* signature);
bool ValidSignature(const char* signature);

// Tests only: forget every registered game.
void ResetForTests();

}  // namespace pse::ids
